import{_ as r,a as e,c as t,ac as s}from"./chunks/framework.BSuaGltH.js";const g=JSON.parse('{"title":"小学三年级数学：独立习题集 · 质量、长度复名数与吨至单价数量、速度时间与两步应用","description":"20 个知识点、40 道小学三年级练习，每题提供默认折叠的答案、步骤和易错说明。","frontmatter":{"title":"小学三年级数学：独立习题集 · 质量、长度复名数与吨至单价数量、速度时间与两步应用","description":"20 个知识点、40 道小学三年级练习，每题提供默认折叠的答案、步骤和易错说明。","splitFrom":"life/math/primary/grade-3/exercises.md","showdocs":{"topics":[{"id":"math","title":"数学","link":"/topics/math/"}],"kind":"习题与解析","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"小学三年级数学：独立习题集","summary":"20 个知识点、40 道小学三年级练习，每题提供默认折叠的答案、步骤和易错说明。","status":"active","related":[{"title":"八年级数学公式速查","link":"/life/math/junior/grade-8/formulas","kind":"公式与参考","scope":"general","audience":"general"},{"title":"八年级数学知识讲解","link":"/life/math/junior/grade-8/knowledge","kind":"知识讲解","scope":"general","audience":"general"},{"title":"八年级数学知识讲解 · 等腰三角形与垂直平分线至加权平均数与方差","link":"/life/math/junior/grade-8/knowledge-part-02","kind":"知识讲解","scope":"general","audience":"general"},{"title":"八年级数学知识讲解 · 平方根、立方根与实数至三角形全等与对应关系","link":"/life/math/junior/grade-8/knowledge-part-01","kind":"知识讲解","scope":"general","audience":"general"},{"title":"程序员数学 01：从编程问题选择学习路线","link":"/life/math/programmer/overview","kind":"知识讲解","scope":"general","audience":"general"}],"prev":{"text":"小学三年级数学：独立习题集 · 多位数乘一位数至一位小数加减与小数点对齐","link":"/life/math/primary/grade-3/exercises-part-01"},"next":false},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"小学三年级数学：独立习题集 · 多位数乘一位数至一位小数加减与小数点对齐","link":"/life/math/primary/grade-3/exercises-part-01"},"next":false},"headers":[],"relativePath":"life/math/primary/grade-3/exercises-part-02.md","filePath":"life/math/primary/grade-3/exercises-part-02.md"}'),p={name:"life/math/primary/grade-3/exercises-part-02.md"};function o(l,a,i,n,d,m){return e(),t("div",null,[...a[0]||(a[0]=[s('<h1 id="小学三年级数学-独立习题集-·-质量、长度复名数与吨至单价数量、速度时间与两步应用" tabindex="-1">小学三年级数学：独立习题集 · 质量、长度复名数与吨至单价数量、速度时间与两步应用 <a class="header-anchor" href="#小学三年级数学-独立习题集-·-质量、长度复名数与吨至单价数量、速度时间与两步应用" aria-label="Permalink to &quot;小学三年级数学：独立习题集 · 质量、长度复名数与吨至单价数量、速度时间与两步应用&quot;">​</a></h1><p><a href="/life/math/primary/grade-3/exercises">返回分篇目录</a></p><p><a href="/life/math/primary/grade-3/knowledge">知识讲解</a> · <a href="/life/math/primary/grade-3/formulas">公式速查</a> · <a href="/life/math/primary/grade-3/exercises">独立习题集</a></p><p>按六三三学段编排的通用建议学习顺序；不同地区、教材和学期安排存在差异。本版覆盖以下明确列出的知识点，不将其等同于所有教材或完整课程标准。</p><h2 id="p3-10" tabindex="-1">质量、长度复名数与吨 <a class="header-anchor" href="#p3-10" aria-label="Permalink to &quot;质量、长度复名数与吨 {#p3-10}&quot;">​</a></h2><p><a href="/life/math/primary/grade-3/knowledge#p3-10">复习讲解</a> · <a href="/life/math/primary/grade-3/formulas#p3-10">公式规则</a></p><h3 id="q19" tabindex="-1">题 19 <a class="header-anchor" href="#q19" aria-label="Permalink to &quot;题 19 {#q19}&quot;">​</a></h3><p>一辆车限载 3 吨，已装 2400 千克，还能装多少千克？</p><p>知识点：p3-10 质量、长度复名数与吨。</p><details class="details custom-block"><summary>查看答案与讲解</summary><p><strong>答案：</strong> 600 千克。</p><p><strong>推导步骤：</strong> 3 吨＝3000 千克，3000−2400＝600 千克。</p><p><strong>易错提醒：</strong> “限载”是最多可装质量，不能超过。</p></details><h3 id="q20" tabindex="-1">题 20 <a class="header-anchor" href="#q20" aria-label="Permalink to &quot;题 20 {#q20}&quot;">​</a></h3><p>一条公路长 2 千米 60 米，已修 850 米，还剩多少米？</p><p>知识点：p3-10 质量、长度复名数与吨。</p><details class="details custom-block"><summary>查看答案与讲解</summary><p><strong>答案：</strong> 1210 米。</p><p><strong>推导步骤：</strong> 总长为 2060 米，2060−850＝1210 米。</p><p><strong>易错提醒：</strong> 2 千米 60 米换成 2060 米，不能换成 2600 米。</p></details><h2 id="p3-11" tabindex="-1">长方形、正方形周长与逆向问题 <a class="header-anchor" href="#p3-11" aria-label="Permalink to &quot;长方形、正方形周长与逆向问题 {#p3-11}&quot;">​</a></h2><p><a href="/life/math/primary/grade-3/knowledge#p3-11">复习讲解</a> · <a href="/life/math/primary/grade-3/formulas#p3-11">公式规则</a></p><h3 id="q21" tabindex="-1">题 21 <a class="header-anchor" href="#q21" aria-label="Permalink to &quot;题 21 {#q21}&quot;">​</a></h3><p>一个长方形操场长 80 米、宽 50 米，沿边跑一圈是多少米？</p><p>知识点：p3-11 长方形、正方形周长与逆向问题。</p><details class="details custom-block"><summary>查看答案与讲解</summary><p><strong>答案：</strong> 260 米。</p><p><strong>推导步骤：</strong> 80＋50＝130 米，这是相邻两边和；再乘 2，得 260 米。</p><p><strong>易错提醒：</strong> 两组对边都要计入。</p></details><h3 id="q22" tabindex="-1">题 22 <a class="header-anchor" href="#q22" aria-label="Permalink to &quot;题 22 {#q22}&quot;">​</a></h3><p>一个正方形的周长是 36 厘米，它的边长是多少？</p><p>知识点：p3-11 长方形、正方形周长与逆向问题。</p><details class="details custom-block"><summary>查看答案与讲解</summary><p><strong>答案：</strong> 9 厘米。</p><p><strong>推导步骤：</strong> 四边相等，36÷4＝9 厘米。</p><p><strong>易错提醒：</strong> 周长平均分成四份，不是两份。</p></details><h2 id="p3-12" tabindex="-1">面积意义与平方单位 <a class="header-anchor" href="#p3-12" aria-label="Permalink to &quot;面积意义与平方单位 {#p3-12}&quot;">​</a></h2><p><a href="/life/math/primary/grade-3/knowledge#p3-12">复习讲解</a> · <a href="/life/math/primary/grade-3/formulas#p3-12">公式规则</a></p><h3 id="q23" tabindex="-1">题 23 <a class="header-anchor" href="#q23" aria-label="Permalink to &quot;题 23 {#q23}&quot;">​</a></h3><p>3 平方分米等于多少平方厘米？</p><p>知识点：p3-12 面积意义与平方单位。</p><details class="details custom-block"><summary>查看答案与讲解</summary><p><strong>答案：</strong> 300 平方厘米。</p><p><strong>推导步骤：</strong> 1 平方分米＝100 平方厘米，3×100＝300。</p><p><strong>易错提醒：</strong> 不能按长度进率乘 10。</p></details><h3 id="q24" tabindex="-1">题 24 <a class="header-anchor" href="#q24" aria-label="Permalink to &quot;题 24 {#q24}&quot;">​</a></h3><p>一张卡片被 4 行、每行 6 个边长 1 厘米的小正方形铺满，无缝无重叠。卡片面积是多少？</p><p>知识点：p3-12 面积意义与平方单位。</p><details class="details custom-block"><summary>查看答案与讲解</summary><p><strong>答案：</strong> 24 平方厘米。</p><p><strong>推导步骤：</strong> 共 4×6＝24 个单位正方形，每个面积为 1 平方厘米。</p><p><strong>易错提醒：</strong> 数方格个数，不能只把行数与列数相加。</p></details><h2 id="p3-13" tabindex="-1">长方形、正方形面积与铺地 <a class="header-anchor" href="#p3-13" aria-label="Permalink to &quot;长方形、正方形面积与铺地 {#p3-13}&quot;">​</a></h2><p><a href="/life/math/primary/grade-3/knowledge#p3-13">复习讲解</a> · <a href="/life/math/primary/grade-3/formulas#p3-13">公式规则</a></p><h3 id="q25" tabindex="-1">题 25 <a class="header-anchor" href="#q25" aria-label="Permalink to &quot;题 25 {#q25}&quot;">​</a></h3><p>长方形菜地长 12 米、宽 7 米，面积是多少平方米？</p><p>知识点：p3-13 长方形、正方形面积与铺地。</p><details class="details custom-block"><summary>查看答案与讲解</summary><p><strong>答案：</strong> 84 平方米。</p><p><strong>推导步骤：</strong> 按长×宽计算，12×7＝84 平方米。</p><p><strong>易错提醒：</strong> 周长是 38 米，与面积是不同的量。</p></details><h3 id="q26" tabindex="-1">题 26 <a class="header-anchor" href="#q26" aria-label="Permalink to &quot;题 26 {#q26}&quot;">​</a></h3><p>长 8 米、宽 6 米的地面，用边长 2 米的正方形地垫整齐铺满，需要多少块？</p><p>知识点：p3-13 长方形、正方形面积与铺地。</p><details class="details custom-block"><summary>查看答案与讲解</summary><p><strong>答案：</strong> 12 块。</p><p><strong>推导步骤：</strong> 长边能排 8÷2＝4 块，宽边能排 6÷2＝3 块，4×3＝12；也可算 48÷4＝12。</p><p><strong>易错提醒：</strong> 每块面积是 2×2＝4 平方米，不是 2 平方米。</p></details><h2 id="p3-14" tabindex="-1">秒与跨整点计时 <a class="header-anchor" href="#p3-14" aria-label="Permalink to &quot;秒与跨整点计时 {#p3-14}&quot;">​</a></h2><p><a href="/life/math/primary/grade-3/knowledge#p3-14">复习讲解</a> · <a href="/life/math/primary/grade-3/formulas#p3-14">公式规则</a></p><h3 id="q27" tabindex="-1">题 27 <a class="header-anchor" href="#q27" aria-label="Permalink to &quot;题 27 {#q27}&quot;">​</a></h3><p>小鹏跑步用了 2 分 15 秒，小林用了 130 秒，谁用时更少，少多少秒？</p><p>知识点：p3-14 秒与跨整点计时。</p><details class="details custom-block"><summary>查看答案与讲解</summary><p><strong>答案：</strong> 小林少 5 秒。</p><p><strong>推导步骤：</strong> 2 分 15 秒＝135 秒，135−130＝5 秒。</p><p><strong>易错提醒：</strong> 比较前先统一单位；用时少表示更快。</p></details><h3 id="q28" tabindex="-1">题 28 <a class="header-anchor" href="#q28" aria-label="Permalink to &quot;题 28 {#q28}&quot;">​</a></h3><p>一段视频从当天 14:48 播放到 15:12，共播放多少分钟？ 15:12 是下午几时几分？另一段视频从 23:50 播放到次日 0:15，共多少分钟？</p><p>知识点：p3-14 秒与跨整点计时。</p><details class="details custom-block"><summary>查看答案与讲解</summary><p><strong>答案：</strong> 24 分钟。 15:12 是下午 3 时 12 分；另一段共 25 分钟。</p><p><strong>推导步骤：</strong> 14:48 到 15:00 为 12 分钟，再到 15:12 为 12 分钟，共 24。 15−12＝3，故为下午 3 时 12 分；跨午夜先算 23:50 到 24:00 的 10 分钟，再加次日 15 分钟，得 25 分钟。</p><p><strong>易错提醒：</strong> 不能直接把 1512−1448 当作分钟差。</p></details><h2 id="p3-15" tabindex="-1">年、月、日与闰年 <a class="header-anchor" href="#p3-15" aria-label="Permalink to &quot;年、月、日与闰年 {#p3-15}&quot;">​</a></h2><p><a href="/life/math/primary/grade-3/knowledge#p3-15">复习讲解</a> · <a href="/life/math/primary/grade-3/formulas#p3-15">公式规则</a></p><h3 id="q29" tabindex="-1">题 29 <a class="header-anchor" href="#q29" aria-label="Permalink to &quot;题 29 {#q29}&quot;">​</a></h3><p>2028 年的二月有多少天？全年有多少天？</p><p>知识点：p3-15 年、月、日与闰年。</p><details class="details custom-block"><summary>查看答案与讲解</summary><p><strong>答案：</strong> 二月 29 天，全年 366 天。</p><p><strong>推导步骤：</strong> 2028÷4＝507，且 2028 不是整百年，所以是闰年。</p><p><strong>易错提醒：</strong> 必须先判断闰年再确定二月天数。</p></details><h3 id="q30" tabindex="-1">题 30 <a class="header-anchor" href="#q30" aria-label="Permalink to &quot;题 30 {#q30}&quot;">​</a></h3><p>一项活动从 4 月 28 日持续到 5 月 3 日，开始与结束当天都计入，共多少天？</p><p>知识点：p3-15 年、月、日与闰年。</p><details class="details custom-block"><summary>查看答案与讲解</summary><p><strong>答案：</strong> 6 天。</p><p><strong>推导步骤：</strong> 四月有 30 天，4 月 28、29、30 共 3 天，5 月 1、2、3 共 3 天，总计 6 天。</p><p><strong>易错提醒：</strong> 本题明确两端都计入，不能只算日期差。</p></details><h2 id="p3-16" tabindex="-1">八个方向与观察物体 <a class="header-anchor" href="#p3-16" aria-label="Permalink to &quot;八个方向与观察物体 {#p3-16}&quot;">​</a></h2><p><a href="/life/math/primary/grade-3/knowledge#p3-16">复习讲解</a> · <a href="/life/math/primary/grade-3/formulas#p3-16">公式规则</a></p><h3 id="q31" tabindex="-1">题 31 <a class="header-anchor" href="#q31" aria-label="Permalink to &quot;题 31 {#q31}&quot;">​</a></h3><p>地图上北下南，医院在公园的西北方向。公园在医院的什么方向？</p><p>知识点：p3-16 八个方向与观察物体。</p><details class="details custom-block"><summary>查看答案与讲解</summary><p><strong>答案：</strong> 东南方向。</p><p><strong>推导步骤：</strong> 从医院返回公园，水平方向由西变东，竖直方向由北变南，合起来为东南。</p><p><strong>易错提醒：</strong> 不能仍答西北，参照物已经交换。</p></details><h3 id="q32" tabindex="-1">题 32 <a class="header-anchor" href="#q32" aria-label="Permalink to &quot;题 32 {#q32}&quot;">​</a></h3><p>两个同样的正方体竖直叠放，位置完全对齐。从正面和正上方分别能看到几个小正方形？</p><p>知识点：p3-16 八个方向与观察物体。</p><details class="details custom-block"><summary>查看答案与讲解</summary><p><strong>答案：</strong> 正面看到 2 个上下排列的小正方形；正上方看到 1 个。</p><p><strong>推导步骤：</strong> 正面能区分两层；上层正方体从上方遮住下层的顶面。</p><p><strong>易错提醒：</strong> 可见方格数与实际正方体数量不总相同。</p></details><h2 id="p3-17" tabindex="-1">复式统计表与数据比较 <a class="header-anchor" href="#p3-17" aria-label="Permalink to &quot;复式统计表与数据比较 {#p3-17}&quot;">​</a></h2><p><a href="/life/math/primary/grade-3/knowledge#p3-17">复习讲解</a> · <a href="/life/math/primary/grade-3/formulas#p3-17">公式规则</a></p><h3 id="q33" tabindex="-1">题 33 <a class="header-anchor" href="#q33" aria-label="Permalink to &quot;题 33 {#q33}&quot;">​</a></h3><p>三（1）班男生 18 人、女生 16 人，三（2）班男生 17 人、女生 19 人。两个班共有女生多少人？</p><p>知识点：p3-17 复式统计表与数据比较。</p><details class="details custom-block"><summary>查看答案与讲解</summary><p><strong>答案：</strong> 35 人。</p><p><strong>推导步骤：</strong> 只取女生这一列：16＋19＝35。</p><p><strong>易错提醒：</strong> 不能混入男生人数。</p></details><h3 id="q34" tabindex="-1">题 34 <a class="header-anchor" href="#q34" aria-label="Permalink to &quot;题 34 {#q34}&quot;">​</a></h3><p>同一张表中，三（1）班男生 18 人、女生 16 人，三（2）班男生 17 人、女生 19 人。哪个班人数更多，多多少人？</p><p>知识点：p3-17 复式统计表与数据比较。</p><details class="details custom-block"><summary>查看答案与讲解</summary><p><strong>答案：</strong> 三（2）班多 2 人。</p><p><strong>推导步骤：</strong> 三（1）班共有 34 人，三（2）班共有 36 人，36−34＝2。</p><p><strong>易错提醒：</strong> 需先算各班总人数，不能只比较一个性别。</p></details><h2 id="p3-18" tabindex="-1">确定事件与可能性初步 <a class="header-anchor" href="#p3-18" aria-label="Permalink to &quot;确定事件与可能性初步 {#p3-18}&quot;">​</a></h2><p><a href="/life/math/primary/grade-3/knowledge#p3-18">复习讲解</a> · <a href="/life/math/primary/grade-3/formulas#p3-18">公式规则</a></p><h3 id="q35" tabindex="-1">题 35 <a class="header-anchor" href="#q35" aria-label="Permalink to &quot;题 35 {#q35}&quot;">​</a></h3><p>袋中只有 5 个白球，随机摸出 1 个，摸到白球、黑球分别属于什么事件？</p><p>知识点：p3-18 确定事件与可能性初步。</p><details class="details custom-block"><summary>查看答案与讲解</summary><p><strong>答案：</strong> 摸白球一定发生；摸黑球不可能发生。</p><p><strong>推导步骤：</strong> 袋内所有可抽到的球都是白色，没有黑球。</p><p><strong>易错提醒：</strong> 只能根据袋内现有物体判断，不能假设另有未说明的球。</p></details><h3 id="q36" tabindex="-1">题 36 <a class="header-anchor" href="#q36" aria-label="Permalink to &quot;题 36 {#q36}&quot;">​</a></h3><p>袋内有大小、质地相同的 6 个红球和 2 个蓝球，充分混合后随机摸 1 个，哪种颜色更可能？能保证摸到它吗？</p><p>知识点：p3-18 确定事件与可能性初步。</p><details class="details custom-block"><summary>查看答案与讲解</summary><p><strong>答案：</strong> 红色更可能；不能保证。</p><p><strong>推导步骤：</strong> 红球数量更多，公平抽取时红色机会更大，但 2 个蓝球仍可能被抽中。</p><p><strong>易错提醒：</strong> “更可能”不是“一定”。</p></details><h2 id="p3-19" tabindex="-1">排列、组合与不重复计数 <a class="header-anchor" href="#p3-19" aria-label="Permalink to &quot;排列、组合与不重复计数 {#p3-19}&quot;">​</a></h2><p><a href="/life/math/primary/grade-3/knowledge#p3-19">复习讲解</a> · <a href="/life/math/primary/grade-3/formulas#p3-19">公式规则</a></p><h3 id="q37" tabindex="-1">题 37 <a class="header-anchor" href="#q37" aria-label="Permalink to &quot;题 37 {#q37}&quot;">​</a></h3><p>用数字 0、2、5 组成没有重复数字的两位数，请全部列出。</p><p>知识点：p3-19 排列、组合与不重复计数。</p><details class="details custom-block"><summary>查看答案与讲解</summary><p><strong>答案：</strong> 20、25、50、52，共 4 个。</p><p><strong>推导步骤：</strong> 十位只能选 2 或 5；十位为 2 时个位选 0、5，十位为 5 时个位选 0、2。</p><p><strong>易错提醒：</strong> 02、05 不是两位数。</p></details><h3 id="q38" tabindex="-1">题 38 <a class="header-anchor" href="#q38" aria-label="Permalink to &quot;题 38 {#q38}&quot;">​</a></h3><p>甲、乙、丙、丁四人，每两人握手一次，共握手多少次？</p><p>知识点：p3-19 排列、组合与不重复计数。</p><details class="details custom-block"><summary>查看答案与讲解</summary><p><strong>答案：</strong> 6 次。</p><p><strong>推导步骤：</strong> 甲与其余 3 人握手；乙再与丙、丁握手 2 次；丙再与丁握手 1 次，共 3＋2＋1＝6。</p><p><strong>易错提醒：</strong> 甲乙与乙甲是同一次握手，不能重复计数。</p></details><h2 id="p3-20" tabindex="-1">单价数量、速度时间与两步应用 <a class="header-anchor" href="#p3-20" aria-label="Permalink to &quot;单价数量、速度时间与两步应用 {#p3-20}&quot;">​</a></h2><p><a href="/life/math/primary/grade-3/knowledge#p3-20">复习讲解</a> · <a href="/life/math/primary/grade-3/formulas#p3-20">公式规则</a></p><h3 id="q39" tabindex="-1">题 39 <a class="header-anchor" href="#q39" aria-label="Permalink to &quot;题 39 {#q39}&quot;">​</a></h3><p>同样的钢笔 4 支共 48 元，买 7 支需要多少元？</p><p>知识点：p3-20 单价数量、速度时间与两步应用。</p><details class="details custom-block"><summary>查看答案与讲解</summary><p><strong>答案：</strong> 84 元。</p><p><strong>推导步骤：</strong> 先求单价 48÷4＝12 元，再算 12×7＝84 元。</p><p><strong>易错提醒：</strong> 应先求一支价格，不能把 48 直接乘 7。</p></details><h3 id="q40" tabindex="-1">题 40 <a class="header-anchor" href="#q40" aria-label="Permalink to &quot;题 40 {#q40}&quot;">​</a></h3><p>小林以每小时 5 千米的速度步行 2 小时，再走 3 千米到达终点，全程多少千米？</p><p>知识点：p3-20 单价数量、速度时间与两步应用。</p><details class="details custom-block"><summary>查看答案与讲解</summary><p><strong>答案：</strong> 13 千米。</p><p><strong>推导步骤：</strong> 前两小时走 5×2＝10 千米，再加最后 3 千米，得 13 千米。</p><p><strong>易错提醒：</strong> 3 的单位是千米，不是小时，不能写 5×(2＋3)。</p></details>',114)])])}const c=r(p,[["render",o]]);export{g as __pageData,c as default};
